from typing import Any

def parse_user_id(payload: dict[str, Any]) -> int:
    raw = payload.get("user_id")
    if not isinstance(raw, int):
        raise ValueError("user_id must be an integer")
    return raw

def greeting(user_id: int) -> str:
    return f"Hello user {user_id}"

legacy_payload: dict[str, Any] = {"user_id": 42}
print(greeting(parse_user_id(legacy_payload)))
```

The uncertain legacy value is limited to the adapter; code after validation receives a precise `int`.

